// A forma do objeto ocupa o lugar do tipo, entre chavetas
const ponto: { x: number; y: number } = { x: 10, y: 4 };

// Em várias linhas, o ponto e vírgula é o separador habitual
const livro: {
  titulo: string;
  paginas: number;
  disponivel: boolean;
} = {
  titulo: "Os Maias",
  paginas: 712,
  disponivel: true,
};

// A vírgula também é aceite como separador
const cor: { r: number, g: number, b: number } = { r: 255, g: 0, b: 0 };

console.log(ponto.x + ponto.y); // 14
console.log(livro.titulo); // "Os Maias"
console.log(cor.r); // 255

const perfil = {
  nome: "Ana",
  idade: 34,
  ativo: true,
  etiquetas: ["admin", "leitor"],
};
// inferido: { nome: string; idade: number; ativo: boolean; etiquetas: string[] }

// as propriedades de um objeto são mutáveis, por isso "Ana" alarga-se a string
perfil.nome = "Beatriz";

// @ts-expect-error idade foi inferida como number e não aceita texto
perfil.idade = "34";

// @ts-expect-error a forma inferida é fechada: não se acrescentam propriedades
perfil.telefone = "912345678";

// Fora de um objeto, um const guarda o tipo literal; um let alarga-se
const estadoFixo = "ativo"; // tipo "ativo"
let estadoLivre = "ativo"; // tipo string
estadoLivre = "inativo";

console.log(perfil.nome, estadoFixo, estadoLivre);

const encomenda: {
  numero: string;
  cliente: { nome: string; email: string };
  linhas: { artigo: string; quantidade: number; preco: number }[];
} = {
  numero: "ENC-2024-001",
  cliente: { nome: "Ana Lima", email: "ana@exemplo.pt" },
  linhas: [
    { artigo: "Teclado", quantidade: 1, preco: 49.9 },
    { artigo: "Rato", quantidade: 2, preco: 19.5 },
  ],
};

// A forma aninhada acompanha o acesso até ao fim da cadeia
console.log(encomenda.cliente.nome); // "Ana Lima"

const total = encomenda.linhas.reduce(
  (soma, linha) => soma + linha.quantidade * linha.preco,
  0,
);
console.log(total.toFixed(2)); // "88.90"

// Array<...> é a forma alternativa de escrever o mesmo array de objetos
const vazio: Array<{ artigo: string; quantidade: number }> = [];
console.log(vazio.length); // 0

function descreverPonto(p: { x: number; y: number }): string {
  return `(${p.x}, ${p.y})`;
}

// Com destructuring a anotação vem depois das chavetas e descreve o objeto todo
function distancia({ x, y }: { x: number; y: number }): number {
  return Math.sqrt(x * x + y * y);
}

// O objeto devolvido também tem forma, anotada depois dos parênteses
function criarSessao(nome: string): { nome: string; inicio: number } {
  return { nome, inicio: 0 };
}

console.log(descreverPonto({ x: 3, y: 4 })); // "(3, 4)"
console.log(distancia({ x: 3, y: 4 })); // 5
console.log(criarSessao("Ana").inicio); // 0

const config = { porta: 8080, host: "localhost" };

console.log(config.porta); // 8080

// @ts-expect-error a propriedade chama-se porta: a gralha portra é apanhada aqui
console.log(config.portra);

function ligar(alvo: { host: string; porta: number }): string {
  return `${alvo.host}:${alvo.porta}`;
}

// @ts-expect-error o literal traz timeout, que o tipo do parâmetro não declara
console.log(ligar({ host: "localhost", porta: 8080, timeout: 30 }));

// Já uma variável com propriedades a mais é aceite: tem tudo o que é exigido
const guardado = { host: "localhost", porta: 8080, timeout: 30 };
console.log(ligar(guardado)); // "localhost:8080"

// A mesma forma repetida em cada assinatura: muda-se num sítio, esquece-se noutro
function area(r: { largura: number; altura: number }): number {
  return r.largura * r.altura;
}
function perimetro(r: { largura: number; altura: number }): number {
  return 2 * (r.largura + r.altura);
}

// Com nome: escreve-se uma vez e usa-se em todo o lado, inclusive no retorno
type Retangulo = { largura: number; altura: number };

function escalar(r: Retangulo, fator: number): Retangulo {
  return { largura: r.largura * fator, altura: r.altura * fator };
}

const caixa: Retangulo = { largura: 3, altura: 4 };

console.log(area(caixa), perimetro(caixa)); // 12 14
console.log(escalar(caixa, 2)); // { largura: 6, altura: 8 }

// Chavetas vazias aceitam quase tudo: números, textos, arrays, funções
const numeroComoVazio: {} = 42;
const textoComoVazio: {} = "texto";
const arrayComoVazio: {} = [1, 2, 3];

// @ts-expect-error null e undefined são os dois únicos valores que {} recusa
const nuloComoVazio: {} = null;

const objetoComoVazio: {} = { nome: "Ana" };
// @ts-expect-error o tipo {} não declara propriedade nenhuma
console.log(objetoComoVazio.nome);

// object exclui os primitivos, mas continua sem propriedades conhecidas
const soObjeto: object = { nome: "Ana" };
// @ts-expect-error 42 é primitivo e não é atribuível a object
const naoObjeto: object = 42;

// Record<string, unknown> é o que normalmente se quer dizer com "objeto qualquer"
const dados: Record<string, unknown> = { nome: "Ana", idade: 34 };
const valor = dados["nome"]; // unknown: obriga a verificar antes de usar
if (typeof valor === "string") {
  console.log(valor.toUpperCase()); // "ANA"
}

console.log(numeroComoVazio, textoComoVazio, arrayComoVazio, nuloComoVazio, soObjeto, naoObjeto);

