const artigo: { nome: string; preco: number; emStock: boolean } = {
  nome: "Caneca",
  preco: 7.5,
  emStock: true,
};

function etiqueta(a: { nome: string; preco: number; emStock: boolean }): string {
  const estado = a.emStock ? "disponível" : "esgotado";
  return `${a.nome}: ${a.preco.toFixed(2)} euros (${estado})`;
}

console.log(etiqueta(artigo)); // "Caneca: 7.50 euros (disponível)"

// @ts-expect-error preco foi anotado como number e não aceita texto
artigo.preco = "7.5";

const evento: {
  titulo: string;
  local: { cidade: string; sala: string };
  participantes: { nome: string; email: string }[];
} = {
  titulo: "Workshop de TypeScript",
  local: { cidade: "Braga", sala: "A2" },
  participantes: [
    { nome: "Ana", email: "ana@exemplo.pt" },
    { nome: "Rui", email: "rui@exemplo.pt" },
  ],
};

function resumo(e: {
  titulo: string;
  local: { cidade: string; sala: string };
  participantes: { nome: string; email: string }[];
}): string {
  return `${e.titulo} em ${e.local.cidade}, sala ${e.local.sala}, com ${e.participantes.length} inscritos`;
}

console.log(resumo(evento));
// "Workshop de TypeScript em Braga, sala A2, com 2 inscritos"

console.log(evento.participantes.map((p) => p.email));
// [ 'ana@exemplo.pt', 'rui@exemplo.pt' ]

type Artigo = { nome: string; preco: number };

function aplicarDesconto({ nome, preco }: Artigo, percentagem: number): Artigo {
  return { nome, preco: Number((preco * (1 - percentagem / 100)).toFixed(2)) };
}

const carrinho: Artigo[] = [
  { nome: "Teclado", preco: 50 },
  { nome: "Rato", preco: 20 },
];

const comDesconto = carrinho.map((a) => aplicarDesconto(a, 10));

console.log(comDesconto);
// [ { nome: 'Teclado', preco: 45 }, { nome: 'Rato', preco: 18 } ]

// @ts-expect-error o literal traz cor, que o tipo Artigo não declara
console.log(aplicarDesconto({ nome: "Cabo", preco: 5, cor: "preto" }, 10));

function lerTexto(dados: Record<string, unknown>, chave: string): string {
  const valor = dados[chave];
  return typeof valor === "string" ? valor : "";
}

function lerNumero(dados: Record<string, unknown>, chave: string): number {
  const valor = dados[chave];
  return typeof valor === "number" ? valor : 0;
}

const resposta: Record<string, unknown> = {
  nome: "Ana",
  idade: 34,
  ativo: true,
};

console.log(lerTexto(resposta, "nome")); // "Ana"
console.log(lerTexto(resposta, "idade")); // ""
console.log(lerNumero(resposta, "idade")); // 34
console.log(lerNumero(resposta, "ausente")); // 0

const comoVazio: {} = resposta;
// @ts-expect-error com {} nem sequer se consegue indexar por chave
console.log(comoVazio["nome"]);
